insert into public.wine_source_evidence select * from pg_temp.wine_recovery_batch on conflict (wine_id,source_revision) do nothing;

do $verify$ begin if exists (select 1 from pg_temp.wine_recovery_batch s join public.wine_source_evidence t using (wine_id,source_revision) where to_jsonb(t) is distinct from to_jsonb(s)) then raise exception 'Conflicting historical evidence; this import part was not committed'; end if; end $verify$;

select '014-wine-source-evidence.sql'::text as completed_part, count(*)::integer as present_records from pg_temp.wine_recovery_batch s join public.wine_source_evidence t using (wine_id,source_revision);

commit;

